# A "diagonal" would be 4s at (r,c) and (r+dr, c+dc) where |dr| == |dc|

print("Checking diagonal 4-pairs:\n")

# For each position, check if it's "diagonally between" 4s
# Two 4s define a diagonal if they're at opposite corners of square/rectangle

def has_diagonal_4s_in_neighborhood(r, c, grid):
    """Check if position (r,c) is diagonally between 4s in the grid"""
    for dr in range(-2, 3):
        for dc in range(-2, 3):
            if dr == 0 and dc == 0:
                continue
            # Check if (r,c) is the midpoint of a diagonal segment
            # i.e., there are 4s at (r-dr/2 + dr/2, c-dc/2 + dc/2)
            # This works if dr and dc are both even
            if dr % 2 == 0 and dc % 2 == 0 and dr != 0 and dc != 0:
                # Midpoint
                nr1, nc1 = r - dr//2, c - dc//2
                nr2, nc2 = r + dr//2, c + dc//2
                if 0 <= nr1 < len(grid) and 0 <= nc1 < len(grid[0]):
                    if 0 <= nr2 < len(grid) and 0 <= nc2 < len(grid[0]):
                        if grid[nr1][nc1] == 4 and grid[nr2][nc2] == 4:
                            return True, ((nr1, nc1), (nr2, nc2))
    return False, None

